70	export function stopRequested(comments: StopComment[], since: Date): boolean {
71	  return comments.some((c) => {
72	    // A stop tag counts only where the machinery is speaking. The notice that preserves
73	    // a removed comment carries that comment verbatim, and a stop tag inside the
74	    // preserved text is the DELETED author's words on a notice whose own line says the
75	    // comment will not be acted on -- acting on it would stop a run the notice told
76	    // somebody would keep going. Preserved text is always fenced (`lib/removed-comment.ts`),
77	    // so the prose is the machinery's own speech.
78	    //
79	    // Not `isQuotation`: a stop RECEIPT quotes the removed comment too, and its stop tag
80	    // is in its prose. Refusing every body that quotes anybody made `/stop` + `/reviewer`
81	    // delete the comment, say the run would stop, and leave the run going (#297).
82	    if (!STOP_TAG.hasProse(c.body ?? "")) return false;
83	    const at = c.created_at ? Date.parse(c.created_at) : NaN;
84	    // An unparseable timestamp is not a reason to ignore a stop somebody asked for.
85	    // The failure it risks -- stopping one run early -- is recoverable by a comment;
86	    // the other direction is a run nobody can interrupt.
87	    return Number.isNaN(at) || at > since.getTime();
