93	 *
94	 * Not `listComments`, deliberately: that reader answers "every comment on this node",
95	 * and this asks "anything NEW since this run started", once every 30 seconds. Re-reading
96	 * a long thread on every poll would cost the whole thread to learn about one comment,
97	 * and `?since=` is the API's own answer to exactly this question. It is a delta, one
98	 * page, with its own failure answer (`false`: this poll learned nothing, and the next
99	 * one asks again).
100	 */
101	function poll(repo: string, number: string, since: Date): boolean {
102	  const { code, stdout } = gh(
103	    "api", `repos/${repo}/issues/${number}/comments`,
104	    "--method", "GET",
105	    "-f", `since=${since.toISOString()}`,
106	    "--jq", "[.[] | {body, created_at}]",
107	  );
108	  if (code !== 0) return false;
109	  try {
110	    return stopRequested(JSON.parse(stdout || "[]") as StopComment[], since);
111	  } catch {
112	    return false;
113	  }
